# Servidor de eco: dice con qué dirección y puerto ve al cliente
import socketserver
class H(socketserver.BaseRequestHandler):
    def handle(self):
        ip, puerto = self.client_address
        self.request.sendall(f"te veo como {ip}:{puerto}\n".encode())
        print(f"conexion desde {ip}:{puerto}", flush=True)
class S(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
S(("0.0.0.0", 9000), H).serve_forever()

