// Un NAT de puertos (PAT) en 35 líneas: reescribe el origen al salir y deshace la traducción al volver
class Nat {
  constructor(ipPublica) {
    this.ip = ipPublica;
    this.salida = new Map();   // "ipPriv:puertoPriv" -> puerto externo
    this.entrada = new Map();  // puerto externo -> "ipPriv:puertoPriv"
    this.proximo = 20000;      // desde dónde buscar un puerto libre cuando el original está ocupado
  }
  // Un paquete sale de la LAN hacia Internet
  saliente(ipPriv, puertoPriv, destino) {
    const clave = `${ipPriv}:${puertoPriv}`;
    if (!this.salida.has(clave)) {
      let ext = puertoPriv;                                  // primero intenta conservar el puerto
      while (this.entrada.has(ext)) ext = this.proximo++;    // si está ocupado, elige otro
      this.salida.set(clave, ext);
      this.entrada.set(ext, clave);
    }
    return { origen: `${this.ip}:${this.salida.get(clave)}`, destino };
  }
  // Un paquete llega de Internet a la IP pública
  entrante(puertoExterno) {
    const interno = this.entrada.get(puertoExterno);
    return interno ? { entregar_a: interno } : { descartado: `no hay mapeo para el puerto ${puertoExterno}` };
  }
}

const nat = new Nat("203.0.113.7");
console.log("1)", nat.saliente("192.168.1.10", 40000, "203.0.113.80:9000"));
console.log("2)", nat.saliente("192.168.1.20", 40000, "203.0.113.80:9000"));   // mismo puerto de origen que el 1
console.log("3)", nat.saliente("192.168.1.10", 40000, "198.51.100.5:443"));    // misma conexión interna, otro destino
console.log("4) llega respuesta al 20000:", nat.entrante(20000));
console.log("5) llega algo al 8080 sin que nadie lo haya pedido:", nat.entrante(8080));
console.log("tabla:", [...nat.salida.entries()]);
